import { useState, useEffect, useRef } from "react";

interface UseInViewOptions extends IntersectionObserverInit {
  onChange?: (entry: IntersectionObserverEntry) => void;
}

export function useInView<T extends HTMLElement>(options?: UseInViewOptions) {
  const [isIntersecting, setIsIntersecting] = useState(false);
  const elementRef = useRef<T | null>(null);

  useEffect(() => {
    const { onChange, ...observerOptions } = options || {};

    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);

      if (onChange) {
        onChange(entry);
      }
    }, observerOptions);

    const currentElement = elementRef.current;

    if (currentElement) {
      observer.observe(currentElement);
    }

    return () => {
      if (currentElement) {
        observer.unobserve(currentElement);
      }
    };
  }, [options]);

  return [elementRef, isIntersecting] as const;
}

export async function $fetch<T>(url: string, init: RequestInit = {}) {
  const token = "<retrieve token logic>";

  return fetch(`${ENDPOINT}${url}`, {
    ...init,
    headers: Object.assign(
      { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      init.headers || {},
    ),
  }).then(async (response) => {
    const content = response.headers
      .get('Content-Type')
      ?.includes('application/json')
        ? ((await response.json()) as T)
        : response;

    if (!response.ok) {
      // other codes as well could be handled there, e.g. through switch
      // or map of {code: factory}
      if (response.status === 401) {
        throw APIAuthError(content);
      } else if (response.status === 500) {
        throw new APIError(content);
      }
    }

    return { response, data: content as T };
  });
}
